def solve():
    edges = []
    for g in range(4):
        edges.append((g*3 + 0, g*3 + 1))
        edges.append((g*3 + 1, g*3 + 2))
        edges.append((g*3 + 0, g*3 + 2))
    for g in range(3):
        for i in range(3):
            edges.append((g*3 + i, (g+1)*3 + i))

    adj = [[] for _ in range(12)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # Order vertices by degree or just sequentially
    # Let's order them sequentially

    labels = [-1] * 12
    used_labels = [False] * 22
    used_diffs = [False] * 22

    def search(idx):
        if idx == 12:
            return True

        # Try all possible labels for vertex idx
        for l in range(22):
            if used_labels[l]: continue

            # Check if this label is valid with already assigned neighbors
            valid = True
            diffs_to_add = []
            for neighbor in adj[idx]:
                if labels[neighbor] != -1:
                    diff = abs(l - labels[neighbor])
                    if diff == 0 or used_diffs[diff] or diff in diffs_to_add:
                        valid = False
                        break
                    diffs_to_add.append(diff)

            if valid:
                labels[idx] = l
                used_labels[l] = True
                for d in diffs_to_add:
                    used_diffs[d] = True

                if search(idx + 1):
                    return True

                labels[idx] = -1
                used_labels[l] = False
                for d in diffs_to_add:
                    used_diffs[d] = False

        return False

    # Symmetry breaking: label 0 can be assigned to vertex 0
    # Actually, 0 and 21 are symmetric. Also the graph has symmetries.
    # Let's just run it.
    if search(0):
        print("SAT")
        print(labels)
    else:
        print("UNSAT")

solve()
